const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const center = ee.Geometry.Point([-73.845369, -9.799994]);
  const roi = center.buffer(5000); // 5km radius

  // Date ranges (single day for each)
  const date2017 = '2017-08-23';
  const date2022 = '2022-08-21';

  // 2. Data Acquisition
  function getForestImage(date) {
    const collection = ee.ImageCollection('COPERNICUS/S2_SR')
      .filterBounds(roi)
      .filterDate(date, ee.Date(date).advance(1, 'day'));

    if (collection.size().getInfo() === 0) return null;

    // Get least cloudy image and mask clouds
    const image = collection.sort('CLOUDY_PIXEL_PERCENTAGE').first();
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));

    const masked = image.updateMask(mask);

    // Calculate NDVI and forest mask
    const ndvi = masked.normalizedDifference(['B8', 'B4']).rename('NDVI');
    const forest = ndvi.gt(0.6); // Forest threshold

    return forest;
  }

  const forest2017 = getForestImage(date2017);
  const forest2022 = getForestImage(date2022);

  // Check for empty collections
  if (!forest2017 || !forest2022) {
    const count2017 = ee.ImageCollection('COPERNICUS/S2_SR')
      .filterBounds(roi)
      .filterDate(date2017, ee.Date(date2017).advance(1, 'day'))
      .size().getInfo();
    const count2022 = ee.ImageCollection('COPERNICUS/S2_SR')
      .filterBounds(roi)
      .filterDate(date2022, ee.Date(date2022).advance(1, 'day'))
      .size().getInfo();

    print(`2017 Images: ${count2017}, 2022 Images: ${count2022}`);
    print("<answer>C1</answer>");
    return;
  }

  // 3. Calculate forest areas
  function calculateForestArea(forestImg, date) {
    const pixelArea = ee.Image.pixelArea(); // Area in m²

    // Count forest pixels and calculate area
    const forestArea = forestImg.multiply(pixelArea);

    const stats = forestArea.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: roi,
      scale: 100,
      maxPixels: 1e9
    });

    const area = stats.get('NDVI').getInfo();
    const pixelCount = forestImg.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: roi,
      scale: 100,
      maxPixels: 1e9
    }).get('NDVI').getInfo();

    return {area: area, pixels: pixelCount};
  }

  const area2017 = calculateForestArea(forest2017, '2017');
  const area2022 = calculateForestArea(forest2022, '2022');

  // Check for no valid pixels
  if (area2017.pixels === 0 || area2022.pixels === 0) {
    print(`2017 Forest Pixels: ${area2017.pixels}, 2022 Forest Pixels: ${area2022.pixels}`);
    print("<answer>C2</answer>");
    return;
  }

  // Check for calculation failure
  if (area2017.area === null || area2022.area === null || 
      isNaN(area2017.area) || isNaN(area2022.area)) {
    print("<answer>C3</answer>");
    return;
  }

  // 4. Compare and output result
  print(`2017 Forest Area: ${(area2017.area / 1e6).toFixed(2)} km² (Pixels: ${area2017.pixels})`);
  print(`2022 Forest Area: ${(area2022.area / 1e6).toFixed(2)} km² (Pixels: ${area2022.pixels})`);

  if (area2022.area > area2017.area) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
